import {EditorView, basicSetup} from 'codemirror';
import {EditorState} from '@codemirror/state';
import {keymap} from '@codemirror/view';
import {indentWithTab, toggleLineComment, undo, redo} from '@codemirror/commands';
import {HighlightStyle, syntaxHighlighting} from '@codemirror/language';
import {tags} from '@lezer/highlight';
import {python} from '@codemirror/lang-python';
import {javascript} from '@codemirror/lang-javascript';
import {cpp} from '@codemirror/lang-cpp';
import {java} from '@codemirror/lang-java';
import {sql} from '@codemirror/lang-sql';

const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api = (operation, params={}) => window.practicecode.invoke(operation, params);
const clone = value => JSON.parse(JSON.stringify(value));
const state = {section:localStorage.getItem('section') || 'problems', course:localStorage.getItem('course') || 'llm', collection:'all', language:'python', focus:'split', statementTab:'Description', workspaceTab:'Code', consoleTab:'Test cases', expanded:true, running:false, designTab:'Diagram', selectedNode:null, undo:[], redo:[], id:null, workspace:null};
let boot, editor, referenceEditor, dirty={}, saveTimer, saveChain=Promise.resolve(), result, noticeTimer, dialogAction;
const languages={python, javascript, cpp, java, sql};
const ext={python:'py',javascript:'js',cpp:'cpp',java:'java',sql:'sql'};
const syntax=HighlightStyle.define([{tag:tags.keyword,color:'var(--keyword)'},{tag:tags.string,color:'var(--string)'},{tag:tags.number,color:'var(--number)'},{tag:tags.comment,color:'var(--secondary)'}]);
function listen(id,event,handler){$(id).addEventListener(event,e=>{Promise.resolve().then(()=>handler(e)).catch(error);});}
function error(reason){$('save-status').textContent=Object.keys(dirty).length?'Save failed':$('save-status').textContent;notice(reason.message || String(reason),true);}
function notice(text,failure=false){clearTimeout(noticeTimer);$('notice').textContent=text;$('notice').hidden=false;$('notice').style.borderColor=failure?'var(--hard)':'var(--border)';noticeTimer=setTimeout(()=>$('notice').hidden=true,failure?12000:5000);}
function record(id=state.id){return boot.progress[String(id)] || {status:'Unstarted',favorite:false,notes:''};}
function currentCatalog(){return state.section==='learning'?boot.lessons:boot.catalog;}
function course(){return boot.courses.find(x=>x.id===state.course) || boot.courses[0];}
function idsOf(collection){return collection?.questionIDs || collection?.groups?.flatMap(x=>x.questionIDs) || [];}
function currentIDs(){if(state.section==='learning')return idsOf(course());if(state.collection==='all')return boot.catalog.map(x=>x.id);if(state.collection==='sql')return boot.catalog.filter(x=>x.tags.includes('Database')).map(x=>x.id);return idsOf([...boot.playlists,...boot.lists].find(x=>x.id===state.collection));}
function allowedRows(){const byID=new Map(currentCatalog().map(p=>[p.id,p]));return currentIDs().map(id=>byID.get(id)).filter(Boolean);}
function filteredRows(){const query=$('search').value.toLowerCase().trim(),difficulty=$('difficulty').value,status=$('status').value,topic=$('topic').value;return allowedRows().filter(p=>(!query || `${p.id} ${p.title} ${p.tags.join(' ')}`.toLowerCase().includes(query))&&(difficulty==='All'||p.difficulty===difficulty)&&(topic==='All'||p.tags.includes(topic))&&(status==='All'||status==='Favorites'&&record(p.id).favorite||status==='Premium'&&p.premium||record(p.id).status===status));}
function applyTheme(mode){document.documentElement.dataset.theme=mode==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):mode;if(state.problem)renderStatement();}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(boot?.settings.appearanceMode==='system')applyTheme('system');});
function account(response){for(const key of ['progress','activity','lists','settings'])if(response[key])boot[key]=response[key];renderStatus();renderSidebar();}
function edited(patch){if(state.workspace?.files&&patch.code!==undefined){state.workspace.files[state.workspace.selectedFile]=patch.code;patch.files=clone(state.workspace.files);}if(patch.files){for(const [id,step] of Object.entries(boot.courseSteps||{})){if(step.workspaceID===state.problem.course?.workspaceID&&boot.progress[id])boot.progress[id].status="In progress";}}Object.assign(state.workspace,Object.fromEntries(Object.entries(patch).filter(([key])=>!['notes','favorite'].includes(key))));Object.assign(dirty,patch);$('save-status').textContent='Saving…';if(Object.keys(patch).some(k=>!['notes','favorite','design'].includes(k)))boot.progress[String(state.id)]={...record(),status:'In progress'};renderStatus();clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(error),400);}
async function flush(){clearTimeout(saveTimer);if(!Object.keys(dirty).length)return saveChain;const patch=dirty,id=state.id,language=state.language;dirty={};saveChain=saveChain.catch(()=>{}).then(async()=>{try{const saved=await api('save',{id,language,patch});boot.progress[String(id)]={...record(id),...saved.record};if(state.id===id&&state.language===language){state.testError=saved.testError;$('save-status').textContent=Object.keys(dirty).length?'Saving…':'Saved';renderStatus();}return saved;}catch(failure){if(state.id===id&&state.language===language)dirty={...patch,...dirty};throw failure;}});return saveChain;}
function renderStatus(){if(!boot||!state.problem)return;$('progress-status').textContent=record().status;$('favorite').textContent=record().favorite?'Favorited':'Favorite';$('favorite').setAttribute('aria-label',record().favorite?'Remove from favorites':'Add to favorites');$('run').disabled=!state.running&&!!state.testError;$('run').querySelector('span').textContent=state.running?'Stop':state.problem?.course?'Run required checks':state.language==='sql'?'Run query':'Run code';$('line-count').textContent=`${(state.workspace.code.match(/\n/g)||[]).length+1} lines · UTF-8`;$('random').disabled=state.running;if(state.problem.course){for(const e of $('course-tools').querySelectorAll('button,select'))e.disabled=state.running;}}
function renderCollections(){const learning=state.section==='learning';$('problems').classList.toggle('active',!learning);$('learning').classList.toggle('active',learning);$('search').placeholder=learning?'Search lessons…':'Search problems…';$('collection-label').textContent=learning?'Track':'Collection';$('collection').innerHTML=learning?boot.courses.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join(''):`<option value="all">All questions</option><option value="sql">All SQL questions</option><optgroup label="My lists">${boot.lists.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</optgroup><optgroup label="LeetCode study plans">${boot.playlists.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</optgroup>`;$('collection').value=learning?state.course:state.collection;$('collection-tools').innerHTML=learning?'<button id="track-info">Track details</button>':'<button id="manage-lists">Manage my lists…</button>';
$('collection-tools').querySelector('button').onclick=()=>learning?showInfo(course().name,course().summary):manageLists();$('topic').innerHTML='<option>All</option>'+[...new Set(currentCatalog().flatMap(p=>p.tags))].sort().map(t=>`<option>${esc(t)}</option>`).join('');$('membership').hidden=learning;$('breadcrumb').textContent=learning?`Learning / ${course().name}`:'Problems';renderSidebar();}
function renderSidebar(){if(!boot)return;const rows=filteredRows(),positions=new Map(currentIDs().map((id,i)=>[id,i+1])),learning=state.section==='learning';let group='';const source=learning?course():boot.playlists.find(p=>p.id===state.collection);const groups=new Map((source?.groups||[]).flatMap(g=>g.questionIDs.map(id=>[id,g.name])));$('library').innerHTML=rows.map(p=>{const g=groups.get(p.id),heading=g&&g!==group?`<div class="group">${esc(g)}</div>`:'';group=g;return heading+`<button role="listitem" class="question-row ${state.id===p.id?'active':''}" data-question="${p.id}" aria-current="${state.id===p.id?'true':'false'}"><span class="row-title">${record(p.id).status==='Solved'?'✓ ':record(p.id).status==='In progress'?'◐ ':''}${learning?positions.get(p.id):p.id}. ${esc(p.title)}</span><span class="row-meta"><span class="${p.difficulty}">${p.difficulty}</span>${p.premium?'<span class="muted">Premium</span>':''}${record(p.id).favorite?'<span class="muted">Favorite</span>':''}</span></button>`;}).join('')||'<p class="muted">No matching questions. Clear your filters or add questions to this list.</p>';$('library-summary').textContent=`${currentCatalog().filter(p=>record(p.id).status==='Solved').length} ${learning?'completed':'solved'} · ${rows.length.toLocaleString()} shown`;
if(learning){const ids=idsOf(course()),done=ids.filter(id=>record(id).status==='Solved').length;$('track-progress').innerHTML=`<div class="progress-row"><span>${done} / ${ids.length} completed</span><button id="resume">Resume</button></div><progress value="${done}" max="${ids.length}"></progress>`;$('resume').onclick=()=>select(ids.find(id=>record(id).status!=='Solved')||ids[0]).catch(error);}else $('track-progress').innerHTML='';renderLessonNavigation();}
function renderLessonNavigation(){const learning=state.section==='learning';$('lesson-navigation').hidden=!learning;if(learning){const ids=idsOf(course()),index=ids.indexOf(state.id);$('step').textContent=`Step ${index+1} of ${ids.length}`;$('previous').disabled=index<=0||state.running;$('next').disabled=index>=ids.length-1||state.running;}}
function clearFilters(){$('search').value='';$('difficulty').value='All';$('status').value='All';$('topic').value='All';}
async function section(next){if(state.running)return;await flush();state.section=next;localStorage.setItem('section',next);clearFilters();renderCollections();const ids=currentIDs();await select(ids.find(id=>next==='learning'&&record(id).status!=='Solved')||ids[0]);}
async function select(id,language){if(!id||state.running)return;await flush();const p=[...boot.catalog,...boot.lessons].find(x=>x.id===id);if(!p)return;state.language=language|| (id<0?'python':p.tags.includes('Database')?'sql':state.language==='sql'?'python':state.language);const opened=await api('open',{id,language:state.language});state.id=id;state.problem=opened.problem;state.courseStarters=opened.starterFiles;state.workspace=opened.workspace;state.testError=opened.testError;state.undo=[];state.redo=[];state.selectedNode=opened.workspace.design?.diagram.components[0]?.id;result=null;state.workspaceTab='Code';renderQuestion();renderSidebar();renderCode();renderTests();renderResult();showWorkspaceTab('Code');}
function renderQuestion(){const p=state.problem;$('source').hidden=!p.sourceURL;$('question-title').textContent=state.section==='learning'?p.title:`${p.id}. ${p.title}`;$('difficulty-badge').textContent=p.difficulty;$('difficulty-badge').className=p.difficulty;$('tags').innerHTML=p.tags.map(t=>`<button data-topic="${esc(t)}">${esc(t)}</button>`).join('');$('attribution').textContent=state.section==='learning'?'PracticeCode lesson':'Statement: LeetCode · Archive: Doocs';$('source').textContent=state.section==='learning'?'Further reading':'Source';$('workspace-tabs').querySelector('[data-tab=Architecture]').hidden=!p.tags.includes('System design');$('notes').value=record().notes||'';renderStatus();renderStatement();}
function sanitizedStatement(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set('p h1 h2 h3 h4 h5 strong em b i pre code ul ol li table thead tbody tr th td blockquote br hr a img details summary sup sub span div font'.split(' '));for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.localName)){el.remove();continue;}const src=el.getAttribute('src'),alt=el.getAttribute('alt'),span=el.getAttribute('colspan');for(const attr of [...el.attributes])el.removeAttribute(attr.name);if(el.localName==='img'){if(src?.startsWith('offline://assets/'))el.setAttribute('src','practicecode://library/assets/'+src.slice('offline://assets/'.length));else if(src?.startsWith('data:image/'))el.setAttribute('src',src);if(alt)el.setAttribute('alt',alt);}if(span&&/^\d+$/.test(span))el.setAttribute('colspan',span);}return doc.body.innerHTML;}
function renderStatement(){if(!state.problem)return;for(const button of $('statement-tabs').children)button.classList.toggle('active',button.dataset.tab===state.statementTab);$('statement').hidden=state.statementTab!=='Description';$('solution').hidden=state.statementTab!=='Solutions';$('notes-panel').hidden=state.statementTab!=='Notes';if(state.statementTab==='Solutions'){renderReference();return;}if(state.statementTab!=='Description')return;const css=getComputedStyle(document.documentElement),color=n=>css.getPropertyValue('--'+n).trim(),dark=document.documentElement.dataset.theme==='dark';$('statement').srcdoc=`<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src practicecode: data:; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'"><style>:root{color-scheme:${dark?'dark':'light'}}body{margin:0;padding:18px 24px 40px;color:${color('text')};background:${color('surface')};font:15px/1.75 "Liberation Sans",system-ui,sans-serif;overflow-wrap:anywhere}pre,code{font-family:ui-monospace,monospace;font-size:12.5px;background:${color('editor')};border-radius:5px}code{padding:2px 5px}pre{white-space:pre-wrap;padding:16px;line-height:1.8}pre code{padding:0}h3{margin-top:28px;font-size:19px}img{max-width:100%;height:auto}table{border-collapse:collapse}td,th{border:1px solid ${color('border')};padding:7px}summary{cursor:pointer;color:${color('accent')}}::selection{background:${color('selection')}}a{color:${color('accent')}}</style></head><body>${sanitizedStatement(state.problem.statement)}</body></html>`;}
function editorExtensions(readOnly=false){return [basicSetup,languages[state.language](),syntaxHighlighting(syntax),keymap.of([indentWithTab]),EditorState.readOnly.of(readOnly),EditorView.editable.of(!readOnly),EditorView.theme({'&':{height:'100%'},'.cm-content':{padding:'16px 0'},'.cm-line':{padding:'0 16px'},'.cm-scroller':{lineHeight:'1.75'}})];}
function renderCode(){editor?.destroy();editor=new EditorView({state:EditorState.create({doc:state.workspace.code,extensions:[...editorExtensions(),EditorView.updateListener.of(update=>{if(update.docChanged){state.workspace.code=update.state.doc.toString();edited({code:state.workspace.code});}})]}),parent:$('editor')});$('language').value=state.language;$('language').disabled=state.id<0;$('filename').textContent=state.workspace.selectedFile||`${state.problem.slug}.${ext[state.language]}`;renderCourseFiles();$('mode').value=state.workspace.mode;$('mode').querySelector('[value=sql]').hidden=state.language!=='sql';$('mode').querySelector('[value=function]').hidden=state.language==='sql';$('mode').querySelector('[value=program]').hidden=state.language==='sql';$('save-status').textContent='Saved';renderStatus();if(state.statementTab==='Solutions')renderReference();}
function renderReference(){referenceEditor?.destroy();if(state.problem.course&&record().status==='Unstarted'){$('solution').innerHTML='<h3>Try the exercise first</h3><p>Make an attempt before opening the worked implementation.</p>';return;}$('solution').innerHTML=`<h3>Reference solution · ${esc(state.language)}</h3><p class="muted">Compare your approach after attempting the exercise.</p><div id="reference-editor"></div>`;const reference=state.problem.references[state.language];if(reference)referenceEditor=new EditorView({state:EditorState.create({doc:reference,extensions:editorExtensions(true)}),parent:$('reference-editor')});else $('reference-editor').textContent='No reference is available in this language.';}
function makeField(value){return {id:crypto.randomUUID(),kind:value===null?'Null':Array.isArray(value)?'Array':typeof value==='object'?'Object':typeof value==='number'?'Number':typeof value==='boolean'?'Boolean':'Text',text:typeof value==='string'?value:JSON.stringify(value)};}
function drafts(){if(!state.workspace.testCaseDrafts){try{state.workspace.testCaseDrafts=JSON.parse(state.workspace.tests).map(c=>({id:crypto.randomUUID(),arguments:c.args.map(makeField),expected:makeField(c.expected),unordered:!!c.unordered}));}catch{state.workspace.testCaseDrafts=[];}}return state.workspace.testCaseDrafts;}
function fieldHTML(field,caseIndex,argumentIndex,label){return `<div class="test-field"><span>${esc(label)}</span><select aria-label="${esc(label)} type" data-case="${caseIndex}" data-argument="${argumentIndex}" data-part="kind">${['Number','Text','Boolean','Array','Object','Null'].map(t=>`<option ${field.kind===t?'selected':''}>${t}</option>`).join('')}</select>${['Array','Object'].includes(field.kind)?`<textarea aria-label="${esc(label)}" data-case="${caseIndex}" data-argument="${argumentIndex}" data-part="text">${esc(field.text)}</textarea>`:`<input aria-label="${esc(label)}" value="${esc(field.text)}" ${field.kind==='Null'?'disabled':''} data-case="${caseIndex}" data-argument="${argumentIndex}" data-part="text">`}${argumentIndex==='expected'?'':`<button data-remove-argument="${caseIndex}:${argumentIndex}" aria-label="Remove ${esc(label)}">×</button>`}</div>`;}
function renderTests(){if(!state.workspace)return;if(state.problem?.course){for(const button of $('console-tabs').children){if(button.dataset.tab==='Test cases')button.textContent='Required checks';button.classList.toggle('active',button.dataset.tab===state.consoleTab);}$('test-content').hidden=state.consoleTab!=='Test cases';$('results').hidden=state.consoleTab!=='Results';$('test-content').innerHTML='<h3>Required checks</h3><p>Checks are read-only and grade the current step against your shared workspace.</p><p>Create test_learner.py to add tests, then choose My tests. Demonstrations, benchmarks and written reflections are ungraded.</p>';return;}const mode=state.workspace.mode;for(const button of $('console-tabs').children){if(button.dataset.tab==='Test cases')button.textContent=mode==='sql'?'Schema & data':mode==='program'?'Standard input':'Test cases';button.classList.toggle('active',button.dataset.tab===state.consoleTab);}$('test-content').hidden=state.consoleTab!=='Test cases';$('results').hidden=state.consoleTab!=='Results';if(mode!=='function'){$('test-content').innerHTML=`<label class="stdin-label">${mode==='sql'?'Schema and seed data · SQLite':'Standard input'}<textarea class="stdin-input" id="stdin">${esc(state.workspace.stdin)}</textarea></label>${mode==='sql'?'<p class="muted">Queries use a fresh in-memory SQLite database. Adapt MySQL-specific syntax. Execution alone does not mark a question solved.</p>':''}`;$('stdin').oninput=()=>edited({stdin:$('stdin').value});return;}const cases=drafts(),names=[...((state.problem.samples[0]?.input||'').matchAll(/(?:^|,\s*)([A-Za-z_]\w*)\s*=/g))].map(m=>m[1]);$('test-content').innerHTML=`<div class="case-toolbar"><span>${cases.length} test cases</span><div><button id="load-examples">Load examples</button><button id="add-case" ${cases.length>=50?'disabled':''}>Add case</button></div></div><div id="test-error" class="test-error">${esc(state.testError||'')}</div>`+cases.map((c,i)=>`<div class="test-case"><div class="case-heading"><span>Case ${i+1}</span><button data-remove-case="${i}">Remove case</button></div>${c.arguments.map((f,j)=>fieldHTML(f,i,j,names[j]||`Input ${j+1}`)).join('')}<button data-add-argument="${i}">Add input</button><h4>Expected output</h4>${fieldHTML(c.expected,i,'expected','Expected')}<label class="check"><input type="checkbox" data-unordered="${i}" ${c.unordered?'checked':''}>Compare arrays in any order</label></div>`).join('');$('add-case').onclick=()=>{cases.push({id:crypto.randomUUID(),arguments:[makeField(0)],expected:makeField(0)});saveDrafts();renderTests();};$('load-examples').onclick=async()=>{if(!await confirmAction('Replace test cases?','Your current custom cases will be replaced with the question examples.'))return;state.workspace.testCaseDrafts=null;state.workspace.tests=JSON.stringify(state.problem.samples.filter(s=>s.args!==null&&s.args!==undefined).map(s=>({args:s.args,expected:s.expected})));drafts();saveDrafts();renderTests();};}
function saveDrafts(){state.testError=null;try{state.workspace.tests=JSON.stringify(drafts().map(c=>({args:c.arguments.map(parseField),expected:parseField(c.expected),unordered:!!c.unordered})));if(!drafts().length)throw Error('Provide at least one test case.');}catch(e){state.testError=e.message;}$('test-error')&&($('test-error').textContent=state.testError||'');edited({testCaseDrafts:clone(drafts())});renderStatus();}
function parseField(field){if(field.kind==='Text')return field.text;if(field.kind==='Null')return null;let value;try{value=JSON.parse(field.text);}catch{throw Error(`Enter valid ${field.kind.toLowerCase()} values.`);}if(field.kind==='Number'&&(typeof value!=='number'||!Number.isFinite(value))||field.kind==='Boolean'&&typeof value!=='boolean'||field.kind==='Array'&&!Array.isArray(value)||field.kind==='Object'&&(!value||Array.isArray(value)||typeof value!=='object'))throw Error(`The value does not match ${field.kind}.`);return value;}
function renderResult(){if(!result){$('results').innerHTML='<h3>Ready when you are</h3><p class="muted">'+(state.problem?.course?'Implement this step in its module or project files, then run the required checks.':'Implement the function, review the example cases, then run them.')+'</p>';return;}let rows='';if(state.language==='sql'&&result.success){try{const table=JSON.parse(result.output);rows=`<table class="result-table"><thead><tr>${table.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v===null?'NULL':v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}catch{rows=`<pre>${esc(result.output)}</pre>`;}}else if(result.output)rows=`<pre>${esc(result.output)}</pre>`;$('results').innerHTML=`<h3 class="${result.success?'pass':'fail'}">${esc(result.message)}</h3>${result.duration!==undefined?`<p class="muted">${Number(result.duration).toFixed(2)} seconds</p>`:''}${(result.cases||[]).map(c=>`<article class="result-case"><strong class="${c.passed?'pass':'fail'}">Case ${c.index} · ${c.passed?'Passed':'Failed'}</strong><dl><dt>Input</dt><dd>${esc(c.input)}</dd><dt>Expected</dt><dd>${esc(c.expected)}</dd><dt>Actual</dt><dd>${esc(c.actual)}</dd></dl></article>`).join('')}${rows}<p class="muted">${state.problem.course?'Required checks grade this step; demonstrations, benchmarks, and written reflections are ungraded.':state.section==='learning'?'Checks assess component code. Architecture and written reasoning are ungraded.':'These are your local cases, not LeetCode’s private judge.'}</p>`;}
async function run(action='check'){if(typeof action!=='string')action='check';if(state.running){await api('stop');return;}await flush();if(state.testError)throw Error(state.testError);state.running=true;state.expanded=true;state.workspaceTab='Code';if(state.focus==='question')focus('split');showWorkspaceTab('Code');showConsole();state.consoleTab='Results';result={success:true,message:'Running…',output:'',cases:[]};renderTests();renderResult();renderStatus();renderLessonNavigation();try{const response=await api('run',{id:state.id,language:state.language,action});result=response.result;account(response);}finally{state.running=false;renderResult();renderStatus();renderLessonNavigation();}}
function focus(mode){state.focus=state.focus===mode?'split':mode;document.body.dataset.focus=state.focus;$('focus-question').textContent=state.focus==='question'?'Restore':'Focus';$('focus-code').textContent=state.focus==='code'?'Restore':'Focus';if(state.focus==='code'){state.expanded=false;showConsole();}requestAnimationFrame(()=>editor?.requestMeasure());}
function showConsole(){$('console').hidden=!state.expanded;$('console-divider').hidden=!state.expanded;$('restore-console').hidden=state.expanded;requestAnimationFrame(()=>editor?.requestMeasure());}
function showWorkspaceTab(tab){state.workspaceTab=tab;for(const button of $('workspace-tabs').children)button.classList.toggle('active',button.dataset.tab===tab);$('code-workspace').hidden=tab!=='Code';$('architecture').hidden=tab!=='Architecture';$('run').hidden=tab!=='Code';if(tab==='Architecture')renderDesign();else requestAnimationFrame(()=>editor?.requestMeasure());}
function modal(title,body,footer='',handler=null){if($('dialog').open)$('dialog').close();$('dialog-title').textContent=title;$('dialog-content').innerHTML=body;$('dialog-footer').innerHTML=footer;dialogAction=handler;$('dialog').showModal();}
function showInfo(title,text){modal(title,`<p>${esc(text)}</p>`);}
function confirmAction(title,text){return new Promise(resolve=>{modal(title,`<p>${esc(text)}</p>`,'<button value="cancel">Cancel</button><button class="primary" value="confirm">Continue</button>');$('dialog').addEventListener('close',()=>resolve($('dialog').returnValue==='confirm'),{once:true});});}
function manageLists(){modal('My lists',`<p class="muted">Personal collections stay separate from LeetCode study plans. Deleting a list keeps saved solutions.</p><div class="list-editor"><input id="new-list-name" placeholder="New list name" maxlength="80"><button type="button" id="create-list">Create</button></div>`+boot.lists.map(l=>`<div class="list-editor"><input value="${esc(l.name)}" aria-label="List name" data-list-name="${esc(l.id)}" maxlength="80"><button type="button" data-rename-list="${esc(l.id)}">Rename</button><button type="button" data-delete-list="${esc(l.id)}">Delete</button></div>`).join(''));$('create-list').onclick=async()=>{try{boot.lists=await api('edit_list',{action:'create',name:$('new-list-name').value});renderCollections();manageLists();}catch(e){error(e);}};}
function memberships(){modal('Add to your lists',boot.lists.length?boot.lists.map(l=>`<label class="membership-row"><input type="checkbox" data-member="${esc(l.id)}" ${l.questionIDs.includes(state.id)?'checked':''}>${esc(l.name)}</label>`).join(''):'<p>Create a personal list using Manage my lists in the sidebar.</p>');}
function settings(){const c=boot.coverage;modal('Settings',`<h3>Appearance</h3><div class="setting-options">${['system','light','dark'].map(m=>`<button type="button" data-appearance="${m}" class="${boot.settings.appearanceMode===m?'active':''}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div><p class="muted">System follows your Linux desktop appearance.</p><hr><h3>Offline library</h3><dl class="coverage"><dt>Questions</dt><dd>${boot.catalog.length.toLocaleString()}</dd><dt>Premium included</dt><dd>${boot.catalog.filter(p=>p.premium).length}</dd><dt>SQL questions</dt><dd>${boot.catalog.filter(p=>p.tags.includes('Database')).length}</dd><dt>Complete study plans</dt><dd>${c.completeStudyPlans||boot.playlists.length} of ${boot.playlists.length}</dd><dt>Unavailable diagrams</dt><dd>${c.unavailableImages?.length||0}</dd><dt>Learning lessons</dt><dd>${boot.lessons.length}</dd></dl><p class="muted">${boot.catalog.length?"Library snapshot includes downloaded statements, diagrams, playlists, starters and reference solutions. Local tests do not certify acceptance by LeetCode’s private judge.":"Original courses and Python packages are bundled for offline study. Code: MIT. Prose and diagrams: CC BY 4.0, Nir Tuttnauer. Required local checks grade code; written reflections and deployment are ungraded."}</p><h3>Saved work</h3><p><code>${esc(boot.workDirectory)}</code></p><button type="button" id="reveal-work">Open saved-work folder</button><hr><h3>Local account</h3><p class="muted">Start fresh with a recovery backup. The library and appearance setting are kept.</p><button type="button" id="reset-account">Reset account…</button>`);$('reveal-work').onclick=()=>api('revealWork').catch(error);$('reset-account').onclick=async()=>{try{await flush();const response=await api('reset');if(response){dirty={};account(response);$('dialog').close();await select(state.id);notice(`Account reset. Recovery backup: ${response.backup}`,true);}}catch(e){error(e);}};}
function stats(group='difficulty'){const catalog=currentCatalog(),known=new Set(catalog.map(p=>p.id)),runs=boot.activity.filter(r=>known.has(r.problemID)),solved=catalog.filter(p=>record(p.id).status==='Solved'),days={};for(const run of runs){const date=typeof run.date==='number'?new Date(Date.UTC(2001,0,1)+run.date*1000):new Date(run.date);if(!Number.isNaN(date.getTime()))days[localDay(date)]=(days[localDay(date)]||0)+1;}const today=new Date(),start=new Date(today);start.setFullYear(start.getFullYear()-1);start.setDate(start.getDate()+1);while(start.getDay()!==0)start.setDate(start.getDate()-1);const boxes=[];for(let date=new Date(start);date<=today;date.setDate(date.getDate()+1)){const key=localDay(date),count=days[key]||0;boxes.push(`<span class="activity-day" title="${esc(key)}: ${count} runs" aria-label="${esc(key)}: ${count} runs" ${count?`style="background:var(--accent);opacity:${Math.min(1,.35+count*.15)}"`:''}></span>`);}let streak=0;const cursor=new Date(today);if(!days[localDay(cursor)])cursor.setDate(cursor.getDate()-1);while(days[localDay(cursor)]){streak++;cursor.setDate(cursor.getDate()-1);}const breakdown={};for(const p of solved){const key=group==='difficulty'?p.difficulty:p.id<0?p.tags[0]:p.tags.includes('Database')?'SQL':'Algorithms';breakdown[key]=(breakdown[key]||0)+1;}const colors=['var(--easy)','var(--medium)','var(--hard)','var(--accent)'];let angle=0;const sectors=Object.entries(breakdown).map(([name,count],i)=>{const start=angle;angle+=count/Math.max(1,solved.length)*360;return `${colors[i%colors.length]} ${start}deg ${angle}deg`;});modal('Statistics',`<p class="muted">${state.section==='learning'?'Learning tracks':'Problem library'} · progress updates automatically from your configured function checks.</p><div class="stat-summary"><div><strong>${solved.length}</strong><span>Completed</span></div><div><strong>${catalog.filter(p=>record(p.id).status!=='Unstarted').length}</strong><span>Attempted</span></div><div><strong>${runs.length}</strong><span>Local runs</span></div><div><strong>${streak}</strong><span>Day streak</span></div></div><h3>Activity · last 12 months</h3><div class="activity-scroll"><div class="activity-grid">${boxes.join('')}</div></div><p class="muted">Counts successful, failed and stopped runs.</p><h3>Completed questions</h3><div class="setting-options"><button type="button" data-stats-group="difficulty">Difficulty</button><button type="button" data-stats-group="type">Task type</button></div><div class="chart-row"><div class="pie" role="img" aria-label="${esc(solved.length+' completed; '+Object.entries(breakdown).map(x=>x.join(': ')).join(', '))}" style="background:${sectors.length?`conic-gradient(${sectors.join(',')})`:'var(--border)'}"><span>${solved.length}</span></div><ul class="legend">${Object.entries(breakdown).map(([name,count],i)=>`<li><span><i style="background:${colors[i%colors.length]}"></i>${esc(name)}</span><strong>${count}</strong></li>`).join('')||'<li>Pass your configured tests to complete your first question.</li>'}</ul></div><h3>Remaining by difficulty</h3><table class="remaining"><thead><tr><th>Difficulty</th><th>Solved</th><th>Remaining</th><th>Total</th></tr></thead><tbody>${['Easy','Medium','Hard'].map(diff=>{const total=catalog.filter(p=>p.difficulty===diff).length,done=solved.filter(p=>p.difficulty===diff).length;return `<tr><td class="${diff}">${diff}</td><td>${done}</td><td>${total-done}</td><td>${total}</td></tr>`;}).join('')}</tbody></table><h3>Recent runs</h3>${runs.slice(-8).reverse().map(r=>`<p class="muted">${esc(catalog.find(p=>p.id===r.problemID)?.title)} · ${esc(r.language)} · ${r.stopped?'Stopped':r.success?'Passed':'Failed'}</p>`).join('')||'<p class="muted">No runs yet.</p>'}`);}
function localDay(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function saveDesign(){edited({design:clone(state.workspace.design)});}
function rememberDesign(){state.undo.push(clone(state.workspace.design.diagram));if(state.undo.length>60)state.undo.shift();state.redo=[];}
function newNode(kind){return {id:crypto.randomUUID(),name:kind,kind,x:.5,y:.5,replicas:1,capacityPerReplica:{Client:0,Service:250,Cache:5000,Database:1000,Queue:200}[kind],latencyMilliseconds:kind==='Cache'?1:kind==='Database'?20:10,available:true};}
function arrange(){const nodes=state.workspace.design.diagram.components,cols=Math.min(3,Math.max(1,nodes.length)),rows=Math.ceil(nodes.length/cols)||1;nodes.forEach((n,i)=>{n.x=cols===1?.5:(i%cols)/(cols-1);n.y=(Math.floor(i/cols)+.5)/rows;});}
function renderDesign(){const d=state.workspace.design;if(!d)return;$('architecture').innerHTML=`<div class="design-banner">${record().status==='Solved'?'Component code checks passed':'Component code checks not yet passed'}<br>Diagrams, model estimates, and written reasoning are ungraded.</div><div class="tabs design-tabs">${['Diagram','Experiments','Review'].map(t=>`<button data-design-tab="${t}" class="${state.designTab===t?'active':''}">${t}</button>`).join('')}</div><div class="design-body" id="design-body"></div>`;if(state.designTab==='Diagram')renderDiagram();else if(state.designTab==='Experiments')renderExperiments().catch(error);else renderReview();}
function renderDiagram(){const d=state.workspace.design,selected=d.diagram.components.find(n=>n.id===state.selectedNode);$('design-body').innerHTML=`<div class="design-toolbar"><select id="node-kind" aria-label="Component type">${['Service','Cache','Database','Queue',...(d.diagram.components.some(n=>n.kind==='Client')?[]:['Client'])].map(k=>`<option>${k}</option>`).join('')}</select><button id="add-node" ${d.diagram.components.length>=12?'disabled':''}>Add component</button><button id="arrange-nodes">Arrange</button><button id="undo-design" ${!state.undo.length?'disabled':''}>Undo</button><button id="redo-design" ${!state.redo.length?'disabled':''}>Redo</button></div><div class="design-scroll"><div class="diagram" id="diagram"></div></div><p class="muted">Select a component to edit. Drag to move it or use position sliders. Arrows are forward requests; responses are implicit.</p>${selected?`<h3>Component settings</h3><div class="design-fields"><label class="wide">Name<input data-node-field="name" value="${esc(selected.name)}"></label>${selected.kind!=='Client'?`<label>Replicas<input data-node-field="replicas" type="number" min="1" max="32" value="${selected.replicas}"></label><label>Capacity per replica (requests/s)<input data-node-field="capacityPerReplica" type="number" min="1" max="10000000" value="${selected.capacityPerReplica}"></label><label>Base latency (ms)<input data-node-field="latencyMilliseconds" type="number" min="0" max="60000" value="${selected.latencyMilliseconds}"></label><label class="check">Available<input data-node-field="available" type="checkbox" ${selected.available?'checked':''}></label>`:''}<label>Horizontal<input data-node-field="x" type="range" min="0" max="1" step=".01" value="${selected.x}"></label><label>Vertical<input data-node-field="y" type="range" min="0" max="1" step=".01" value="${selected.y}"></label></div><button id="remove-node">Remove component</button>`:''}<hr><h3>Request flow</h3><div class="design-fields"><label>From<select id="edge-from">${d.diagram.components.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select></label><label>To<select id="edge-to">${d.diagram.components.filter(n=>n.kind!=='Client').map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select></label><label>Label<input id="edge-label" value="request"></label><button id="connect-nodes">Connect</button></div>${d.diagram.connections.map(e=>`<div class="edge-row"><span>${esc(d.diagram.components.find(n=>n.id===e.from)?.name)} → ${esc(d.diagram.components.find(n=>n.id===e.to)?.name)}<br><small>${esc(e.label)}</small></span><button data-remove-edge="${esc(e.id)}" aria-label="Remove connection">Remove</button></div>`).join('')}`;drawDiagram();$('add-node').onclick=()=>{rememberDesign();const node=newNode($('node-kind').value);d.diagram.components.push(node);state.selectedNode=node.id;arrange();saveDesign();renderDiagram();};$('arrange-nodes').onclick=()=>{rememberDesign();arrange();saveDesign();renderDiagram();};$('undo-design').onclick=()=>{if(!state.undo.length)return;state.redo.push(clone(d.diagram));d.diagram=state.undo.pop();saveDesign();renderDiagram();};$('redo-design').onclick=()=>{if(!state.redo.length)return;state.undo.push(clone(d.diagram));d.diagram=state.redo.pop();saveDesign();renderDiagram();};if(selected)$('remove-node').onclick=()=>{rememberDesign();d.diagram.components=d.diagram.components.filter(n=>n.id!==selected.id);d.diagram.connections=d.diagram.connections.filter(e=>e.from!==selected.id&&e.to!==selected.id);state.selectedNode=d.diagram.components[0]?.id;saveDesign();renderDiagram();};$('connect-nodes').onclick=async()=>{try{const from=$('edge-from').value,to=$('edge-to').value;if(from===to||d.diagram.connections.some(e=>e.from===from&&e.to===to))throw Error('Choose different components and a new connection.');const trial=clone(d.diagram);trial.connections.push({id:crypto.randomUUID(),from,to,label:$('edge-label').value});const check=await api('simulate',{diagram:trial,scenario:d.scenario});if(!check.valid)throw Error(check.observations[0]);rememberDesign();d.diagram=trial;saveDesign();renderDiagram();}catch(e){error(e);}};}
function drawDiagram(){const graph=$('diagram'),d=state.workspace.design.diagram,width=graph.clientWidth||520,height=260;const point=n=>({x:16+Math.min(1,Math.max(0,Number(n.x)||0))*(width-156),y:20+Math.min(1,Math.max(0,Number(n.y)||0))*(height-110)});graph.innerHTML=`<svg viewBox="0 0 ${width} ${height}"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 10 5 0 10Z" fill="var(--secondary)"/></marker></defs>${d.connections.map(e=>{const a=d.components.find(n=>n.id===e.from),b=d.components.find(n=>n.id===e.to);if(!a||!b)return '';const p=point(a),q=point(b);return `<path d="M${p.x+124} ${p.y+35} L${q.x} ${q.y+35}" stroke="var(--secondary)" stroke-width="1.5" fill="none" marker-end="url(#arrow)"/>`;}).join('')}</svg>`+d.components.map(n=>{const p=point(n);return `<button class="node ${n.id===state.selectedNode?'selected':''}" data-node="${esc(n.id)}" style="left:${p.x}px;top:${p.y}px"><strong>${esc(n.name)}</strong><small>${n.kind==='Client'?'Request source':n.available?`${n.replicas} × ${Number(n.capacityPerReplica).toLocaleString()} req/s`:'Unavailable'}</small></button>`;}).join('');for(const button of graph.querySelectorAll('.node'))button.addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=d.components.find(n=>n.id===button.dataset.node),rect=graph.getBoundingClientRect();let moved=false;const start={x:e.clientX,y:e.clientY,nx:n.x,ny:n.y};const move=ev=>{if(!moved&&Math.hypot(ev.clientX-start.x,ev.clientY-start.y)<4)return;if(!moved){rememberDesign();moved=true;}n.x=Math.min(1,Math.max(0,start.nx+(ev.clientX-start.x)/(rect.width-156)));n.y=Math.min(1,Math.max(0,start.ny+(ev.clientY-start.y)/(height-110)));drawDiagram();};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);state.selectedNode=n.id;if(moved)saveDesign();renderDiagram();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});});}
function modelHTML(model){return `<div class="design-result"><h3>Capacity estimate</h3><dl><dt>Completed work (model)</dt><dd>${Number(model.completedPerSecond).toFixed(1)} requests/s</dd><dt>Path estimate</dt><dd>${model.uncachedPathMilliseconds===null?'Unavailable':Number(model.uncachedPathMilliseconds).toFixed(1)+' ms'}</dd></dl>${model.stages.map(s=>`<p><strong>${esc(s.name)}</strong> · ${s.utilization===null?'Unavailable':(s.utilization*100).toFixed(0)+'% load'}<br>${s.incoming.toFixed(1)} incoming · ${s.capacity.toFixed(1)} capacity · ${s.completed.toFixed(1)} processed req/s${s.kind==='Queue'?` · ${s.backlog.toFixed(0)} pending`:''}</p>`).join('')}${model.observations.map(o=>`<p>${esc(o)}</p>`).join('')}</div>`;}
async function renderExperiments(){const d=state.workspace.design;$('design-body').innerHTML=`<h3>Test your assumptions</h3><p class="muted">Save a baseline, change one assumption, then compare another run.</p><div class="design-fields">${[['requestsPerSecond','Incoming requests/s'],['readPercent','Reads (%)'],['cacheHitPercent','Cache hits among reads (%)'],['durationSeconds','Duration (seconds)']].map(([key,label])=>`<label>${label}<input data-scenario="${key}" type="number" value="${d.scenario[key]}"></label>`).join('')}</div><button class="primary" id="save-experiment">Run & save experiment</button><div id="model-result"></div><details><summary>Model assumptions and formulas</summary><p class="muted">Educational estimates, not a benchmark or architecture judge. Traffic is steady, replicas balance perfectly, and every forward arrow receives the source’s processed requests. A cache bypasses read share × hit share. A stage processes min(incoming, capacity). Queue growth is max(0, incoming − capacity) × duration. Below saturation, latency is base latency ÷ (1 − utilization), summed on the longest path. Queue waiting, networking, sharding, consistency, tail latency and retries are not modeled.</p></details><h3 style="margin-top:24px">Saved experiments</h3>${d.experiments.map((x,i)=>`<details class="experiment"><summary>${esc(x.name)} · ${x.result.completedPerSecond.toFixed(1)} req/s${i?` · Δ ${(x.result.completedPerSecond-d.experiments[i-1].result.completedPerSecond).toFixed(1)} req/s`:''}</summary>${modelHTML(x.result)}<button data-restore-experiment="${i}">Restore setup</button></details>`).join('')||'<p class="muted">No snapshots yet.</p>'}`;const snapshot=JSON.stringify(d.scenario);const model=await api('simulate',{diagram:d.diagram,scenario:d.scenario});if(state.designTab==='Experiments'&&JSON.stringify(d.scenario)===snapshot&&$('model-result'))$('model-result').innerHTML=modelHTML(model);$('save-experiment')&&($('save-experiment').onclick=async()=>{try{await flush();const response=await api('experiment',{id:state.id,language:state.language});state.workspace.design=response.design;renderExperiments();notice('Experiment saved.');}catch(e){error(e);}});}
function renderReview(){const d=state.workspace.design,fields=[['requirements','Requirements & constraints','Define scope, correctness, latency, and availability targets.'],['capacityReasoning','Capacity reasoning','Estimate traffic, concurrency, storage, and headroom. Explain your experiments.'],['dataModel','Data model','Describe records, keys, indexes, retention, and consistency.'],['requestFlow','Request flow','Walk through a read and a write using your diagram.'],['failureModes','Failure & recovery','What fails first? Explain timeouts, retries, idempotency, and recovery.']];$('design-body').innerHTML=`<div class="design-review"><h3>Explain the design</h3><p class="muted">Your reasoning is saved, but is not automatically graded.</p>${fields.map(([key,label,hint])=>`<label>${label}<small>${hint}</small><textarea data-review="${key}">${esc(d[key])}</textarea></label>`).join('')}<h3>Decisions & tradeoffs</h3><button id="add-decision">Add decision</button>${d.tradeoffs.map((t,i)=>`<section class="decision"><button data-remove-decision="${i}">Remove decision</button>${[['decision','Chosen approach'],['alternative','Alternative'],['benefit','What it gains'],['cost','What it gives up'],['justification','Why this fits']].map(([key,label])=>`<label>${label}<textarea data-tradeoff="${i}:${key}">${esc(t[key])}</textarea></label>`).join('')}</section>`).join('')}</div>`;$('add-decision').onclick=()=>{d.tradeoffs.push({id:crypto.randomUUID(),decision:'',alternative:'',benefit:'',cost:'',justification:''});saveDesign();renderReview();};}

async function advance(delta){const ids=currentIDs(),index=ids.indexOf(state.id);if(index+delta>=0&&index+delta<ids.length)await select(ids[index+delta]);}
listen('problems','click',()=>section('problems'));
listen('learning','click',()=>section('learning'));
listen('search','input',renderSidebar);
listen('filters','click',()=>{$('filter-panel').hidden=!$('filter-panel').hidden;});
for(const id of ['difficulty','status','topic'])listen(id,'change',renderSidebar);
listen('clear-filters','click',()=>{clearFilters();renderSidebar();});
listen('collection','change',async()=>{if(state.running)return;await flush();if(state.section==='learning'){state.course=$('collection').value;localStorage.setItem('course',state.course);}else state.collection=$('collection').value;clearFilters();renderCollections();const ids=currentIDs();if(ids.length)await select(ids[0]);});
listen('library','click',e=>{const button=e.target.closest('[data-question]');if(button)return select(Number(button.dataset.question));});
listen('tags','click',e=>{const button=e.target.closest('[data-topic]');if(button){$('topic').value=button.dataset.topic;$('filter-panel').hidden=false;renderSidebar();}});
listen('statement-tabs','click',e=>{const tab=e.target.closest('[data-tab]');if(tab){state.statementTab=tab.dataset.tab;renderStatement();}});
listen('workspace-tabs','click',e=>{const tab=e.target.closest('[data-tab]');if(tab)showWorkspaceTab(tab.dataset.tab);});
listen('console-tabs','click',e=>{const tab=e.target.closest('[data-tab]');if(tab){state.consoleTab=tab.dataset.tab;renderTests();renderResult();}});
listen('language','change',()=>select(state.id,$('language').value));
listen('mode','change',()=>{edited({mode:$('mode').value});state.testError=null;if(state.workspace.mode==='function')saveDrafts();renderTests();renderStatus();});
listen('notes','input',()=>edited({notes:$('notes').value}));
listen('favorite','click',async()=>{const favorite=!record().favorite;boot.progress[String(state.id)]={...record(),favorite};edited({favorite});await flush();renderSidebar();});
listen('membership','click',memberships);
listen('starter','click',async()=>{if(await confirmAction('Reset starter code?','This replaces your code for the selected language. Notes, test cases, and other languages are kept.')){const code=state.workspace.mode==='course'?(state.courseStarters?.[state.workspace.selectedFile]||''):state.workspace.mode==='program'?boot.programs[state.language]:state.problem.starters[state.language]||boot.programs[state.language];editor.dispatch({changes:{from:0,to:editor.state.doc.length,insert:code}});await flush();}});
listen('export','click',async()=>{await flush();await api('export',{id:state.id,language:state.language});});
listen('run','click',run);
listen('focus-question','click',()=>focus('question'));
listen('focus-code','click',()=>focus('code'));
listen('minimize-console','click',()=>{state.expanded=false;showConsole();});
listen('restore-console','click',()=>{state.expanded=true;showConsole();});
listen('previous','click',()=>advance(-1));listen('next','click',()=>advance(1));
listen('statistics','click',()=>stats());listen('settings','click',settings);
listen('random','click',()=>{const ids=filteredRows().map(p=>p.id).filter(id=>id!==state.id);if(ids.length)return select(ids[Math.floor(Math.random()*ids.length)]);notice('No other matching question.');});
listen('source','click',()=>api('openSource',{id:state.id}));
listen('test-content','input',e=>{const t=e.target;if(t.dataset.part==='text'){const c=drafts()[Number(t.dataset.case)],f=t.dataset.argument==='expected'?c.expected:c.arguments[Number(t.dataset.argument)];f.text=t.value;saveDrafts();}});
listen('test-content','change',e=>{const t=e.target;if(t.dataset.part==='kind'){const c=drafts()[Number(t.dataset.case)],f=t.dataset.argument==='expected'?c.expected:c.arguments[Number(t.dataset.argument)];f.kind=t.value;saveDrafts();renderTests();}if(t.dataset.unordered!==undefined){drafts()[Number(t.dataset.unordered)].unordered=t.checked;saveDrafts();}});
listen('test-content','click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.removeCase!==undefined)drafts().splice(Number(t.dataset.removeCase),1);else if(t.dataset.addArgument!==undefined)drafts()[Number(t.dataset.addArgument)].arguments.push(makeField(0));else if(t.dataset.removeArgument){const [c,a]=t.dataset.removeArgument.split(':').map(Number);drafts()[c].arguments.splice(a,1);}else return;saveDrafts();renderTests();});
listen('dialog-content','click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.appearance){boot.settings=await api('set_settings',{appearanceMode:t.dataset.appearance});applyTheme(t.dataset.appearance);settings();}else if(t.dataset.statsGroup)stats(t.dataset.statsGroup);else if(t.dataset.renameList){boot.lists=await api('edit_list',{action:'rename',listID:t.dataset.renameList,name:[...$('dialog-content').querySelectorAll('[data-list-name]')].find(x=>x.dataset.listName===t.dataset.renameList).value});renderCollections();manageLists();}else if(t.dataset.deleteList){const listID=t.dataset.deleteList;if(await confirmAction('Delete list?','Your saved code, tests, and notes are kept.')){boot.lists=await api('edit_list',{action:'delete',listID});if(state.collection===listID)state.collection='all';renderCollections();}manageLists();}});
listen('dialog-content','change',async e=>{if(e.target.dataset.member){boot.lists=await api('edit_list',{action:'toggle',listID:e.target.dataset.member,questionID:state.id});renderCollections();}});
listen('architecture','click',e=>{const t=e.target.closest('button');if(!t)return;const d=state.workspace.design;if(t.dataset.node){state.selectedNode=t.dataset.node;renderDiagram();}else if(t.dataset.designTab){state.designTab=t.dataset.designTab;renderDesign();}else if(t.dataset.removeEdge){rememberDesign();d.diagram.connections=d.diagram.connections.filter(x=>x.id!==t.dataset.removeEdge);saveDesign();renderDiagram();}else if(t.dataset.removeDecision!==undefined){d.tradeoffs.splice(Number(t.dataset.removeDecision),1);saveDesign();renderReview();}else if(t.dataset.restoreExperiment!==undefined){const x=d.experiments[Number(t.dataset.restoreExperiment)];rememberDesign();d.diagram=clone(x.diagram);d.scenario=clone(x.scenario);saveDesign();renderExperiments().catch(error);}});
listen('architecture','focusin',e=>{if(e.target.dataset.nodeField)rememberDesign();});
listen('architecture','input',e=>{const t=e.target,d=state.workspace.design;if(t.dataset.review){d[t.dataset.review]=t.value;saveDesign();}else if(t.dataset.tradeoff){const [i,key]=t.dataset.tradeoff.split(':');d.tradeoffs[Number(i)][key]=t.value;saveDesign();}else if(t.dataset.scenario){d.scenario[t.dataset.scenario]=Number(t.value);saveDesign();}else if(t.dataset.nodeField){const node=d.diagram.components.find(n=>n.id===state.selectedNode);if(!node)return;node[t.dataset.nodeField]=t.type==='checkbox'?t.checked:t.type==='number'||t.type==='range'?Number(t.value):t.value;saveDesign();if($('diagram'))drawDiagram();}});
function resizePane(id,horizontal){const divider=$(id),update=position=>{if(horizontal){const rect=$('code-workspace').getBoundingClientRect();$('code-workspace').style.setProperty('--console-height',Math.max(150,Math.min(rect.height-190,rect.bottom-position))+'px');}else{const rect=$('workspace').getBoundingClientRect();$('workspace').style.setProperty('--question-width',Math.max(280,Math.min(rect.width-360,position-rect.left-10))+'px');}editor?.requestMeasure();};divider.addEventListener('pointerdown',e=>{e.preventDefault();divider.setPointerCapture(e.pointerId);const move=ev=>update(horizontal?ev.clientY:ev.clientX),up=()=>{divider.removeEventListener('pointermove',move);divider.removeEventListener('pointerup',up);};divider.addEventListener('pointermove',move);divider.addEventListener('pointerup',up,{once:true});});divider.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const rect=divider.getBoundingClientRect();update((horizontal?rect.y:rect.x)+(['ArrowDown','ArrowRight'].includes(e.key)?20:-20));});}
resizePane('pane-divider',false);resizePane('console-divider',true);
window.practicecode.onCommand(command=>{Promise.resolve().then(async()=>{if(command==='save')await flush();else if(command==='run')await run();else if(command==='settings')settings();else if(command==='comment'){editor.focus();toggleLineComment(editor);}else if(command==='undo'||command==='redo'){if(editor.dom.contains(document.activeElement)){(command==='undo'?undo:redo)(editor);}else document.execCommand(command);}else if(command==='previous')await advance(-1);else if(command==='next')await advance(1);else if(command==='close'){await flush();await api('closeReady');}}).catch(error);});
window.addEventListener('error',e=>error(e.error||e.message));
window.addEventListener('unhandledrejection',e=>{e.preventDefault();error(e.reason);});
(async()=>{boot=await api('bootstrap');if(!boot.catalog.length){state.section='learning';$('problems').hidden=true;if(!localStorage.getItem('course'))state.course='python-engineer';}applyTheme(boot.settings.appearanceMode||'system');if(!boot.courses.some(c=>c.id===state.course))state.course=boot.courses[0]?.id;renderCollections();await select(currentIDs()[0]);showConsole();document.body.dataset.ready='true';})().catch(error);

function renderCourseFiles(){const files=state.workspace.files;$('course-tools').hidden=!files;$('mode').closest('.execution-mode').hidden=!!files;if(!files)return;$('course-file').innerHTML=Object.keys(files).sort().map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');$('course-file').value=state.workspace.selectedFile;for(const e of $('course-tools').querySelectorAll('button,select'))e.disabled=state.running;}
async function chooseCourseFile(name){if(state.running)return;await flush();if(!(name in state.workspace.files))throw Error('File no longer exists.');state.workspace.selectedFile=name;state.workspace.code=state.workspace.files[name];edited({selectedFile:name});await flush();renderCode();}
async function manageCourseFile(action){if(state.running)return;await flush();const old=state.workspace.selectedFile;if(action!=='new'&&old===state.problem.course.entrypoint)throw Error('Keep the required entry file. You can edit its contents.');if(action==='delete'){if(!await confirmAction('Delete file?',`Remove ${old} from this workspace? Export a copy first if you need it.`))return;delete state.workspace.files[old];edited({files:clone(state.workspace.files),selectedFile:state.problem.course.entrypoint});await flush();await select(state.id);return;}modal(action==='new'?'New file':'Rename file',`<label>Relative file name<input id="course-filename" value="${action==='rename'?esc(old):''}" placeholder="src/package/helpers.py"></label>`,`<button type="button" id="confirm-course-file">${action==='new'?'Create':'Rename'}</button>`);$('confirm-course-file').onclick=async()=>{try{const name=$('course-filename').value.trim();if(name in state.workspace.files)throw Error('That file already exists.');const files=clone(state.workspace.files);files[name]=action==='rename'?files[old]:'';if(action==='rename')delete files[old];const response=await api('save',{id:state.id,language:state.language,patch:{files,selectedFile:name}});boot.progress[String(state.id)]=response.record;$('dialog').close();await select(state.id);}catch(e){error(e);}};}
listen('course-file','change',()=>chooseCourseFile($('course-file').value));
listen('course-new','click',()=>manageCourseFile('new'));listen('course-rename','click',()=>manageCourseFile('rename'));listen('course-delete','click',()=>manageCourseFile('delete'));
listen('course-export','click',async()=>{await flush();await api('exportWorkspace',{id:state.id,language:state.language});});
listen('course-tools','click',e=>{const action=e.target.closest('[data-course-action]')?.dataset.courseAction;if(action)return run(action);});
